insert into public.brand_dna (team_id, id, created_at, updated_at, mission, aesthetic_keywords, never_do, target_customer, price_positioning, reference_brands) values ('00000000-0000-4000-8000-000000000001', 'f2367b83-3c06-5274-a683-c1e0df46f2c5', '2026-10-01T09:00:00.000Z', '2026-10-01T09:00:00.000Z', 'Goldiesol is building the global benchmark for feminine, delicate, intricately detailed, high-quality swimwear. We win on finer detail — lace, beading, delicate trims, considered hardware — and on a better fit.', array['feminine', 'delicate', 'intricate', 'romantic', 'premium', 'confident', 'sun-kissed', 'lace-led', 'heirloom detail', 'soft sheen'], array['No heavy or oversized logos', 'No neon or fluorescent colours', 'No cheap-looking plastic hardware', 'No beading that cannot pass a pull test', 'No reproducing another brand''s signature design', 'No lace without swim-grade stretch recovery'], 'Women 20–38 who travel for the sun — beach clubs, yachts, honeymoons — and buy fewer, better pieces. Follows influencer-led labels but wants something more refined and more detailed.', 'Premium accessible: above influencer-led labels, below luxury houses. Detail and fit justify the step up.', array['Frankies Bikinis', 'Kulani Kinis']) on conflict (id) do nothing;
